import React from 'react';
import { requireNativeComponent, type NativeSyntheticEvent, type ViewStyle } from 'react-native';
import { type StyleProp } from 'react-native';
import BannerAdSize from './BannerAdSize';
import AdRequest from '../common/AdRequest';
import type { AdInfo } from '../common/Event';
import type {
    BannerViewProps,
    BannerAdError,
    BannerImpressionData,
} from '../types/BannerViewProps.interface';

interface NativeBannerViewProps {
    adSize: BannerAdSize;
    adRequest?: AdRequest;
    onAdLoaded?: (event: NativeSyntheticEvent<{ adInfo?: AdInfo }>) => void;
    onAdClicked?: (event: NativeSyntheticEvent<{}>) => void;
    onAdImpression?: (event: NativeSyntheticEvent<BannerImpressionData>) => void;
    onAdFailedToLoad?: (event: NativeSyntheticEvent<BannerAdError>) => void;
    style?: StyleProp<ViewStyle>;
}

const RNBannerView = requireNativeComponent<NativeBannerViewProps>('BannerView');

/**
 * BannerView component for displaying banner ads.
 *
 * @param {BannerViewProps} props - The properties for the BannerView component.
 *
 * @returns BannerView component.
 */
const BannerView = (props: BannerViewProps) => {
    const {
        size,
        adRequest,
        onAdLoaded,
        onAdClicked,
        onAdImpression,
        onAdFailedToLoad,
        style,
        ...restProps
    } = props;
    const fullAdRequest = new AdRequest(adRequest);
    return (
        <RNBannerView
            adSize={size}
            adRequest={fullAdRequest}
            onAdLoaded={onAdLoaded}
            onAdClicked={onAdClicked}
            onAdImpression={onAdImpression}
            onAdFailedToLoad={onAdFailedToLoad}
            style={[style, size && { height: size.height, width: size.width }]}
            {...restProps}
        />
    );
};

export default BannerView;
