import AdTargeting from './AdTargeting';
import MobileAds from '../MobileAds';
import { mapToObject } from '../util/mapping';
import type { AdRequestParams } from '../types/AdRequestParams.interface';

/**
 * This class is responsible for configuring ad loading.
 */
class AdRequest {
    readonly _adUnitId: string;
    readonly _targeting?: AdTargeting;
    readonly _adTheme?: string;
    readonly _biddingData?: string;
    readonly _parameters?: object;

    /**
     * Constructs an instance of an ad request with the provided data.
     *
     * @param params An object containing ad request parameters. See {@link AdRequestParams} for more details.
     */
    constructor(params: AdRequestParams) {
        const {
            adUnitId,
            targeting,
            adTheme,
            biddingData,
            parameters,
        } = params;

        this._adUnitId = adUnitId;
        this._targeting = targeting ? new AdTargeting(targeting) : undefined;
        this._adTheme = adTheme;
        this._biddingData = biddingData;

        const pluginParameters = {
            plugin_type: 'react-native',
            plugin_version: `${MobileAds.pluginVersion}`,
        };
        this._parameters = { ...pluginParameters, ...mapToObject(parameters) };
    }
}

export default AdRequest;
