import Gender from './Gender';
import Location from './Location';
import type { AdTargetingParams } from '../types/AdTargetingParams.interface';

/**
 * This class is responsible for configuring ad targeting parameters.
 */
class AdTargeting {
    readonly _age?: string;
    readonly _gender?: Gender;
    readonly _location?: Location;
    readonly _contextQuery?: string;
    readonly _contextTags?: string[];

    /**
     * Constructs an instance of ad targeting with the provided data.
     *
     * @param params An object containing ad targeting parameters. See {@link AdTargetingParams} for more details.
     */
    constructor(params: AdTargetingParams = {}) {
        const { age, gender, location, contextQuery, contextTags } = params;
        this._age = age;
        this._gender = gender;
        this._location = location;
        this._contextQuery = contextQuery;
        this._contextTags = contextTags;
    }
}

export default AdTargeting;
